export declare const pictureOf: (grid: DotGrid, painter: DotPainter) => StoryPicture;
/** How long `text` takes to type, so whatever follows can wait for it. */
export declare const typingSeconds: (text: DotStoryText, charactersPerSecond: number) => number;
interface BeatStoryOptions {
    grid: DotGrid;
    beats: StoryBeat[];
    /** The beat the static art shows, and how far into its hold. */
